import pandas as pd
import numpy as np

# Load the data
gas_data = pd.read_csv('getisord_2023_gas.csv')
adjacency_data = pd.read_csv('borough_adjacency.csv')

# Check for missing values and exclude rows with missing values
gas_data = gas_data.dropna()

# Calculate combined local areas
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhoods:
        neighborhoods[borough] = []
    neighborhoods[borough].append(neighbor)
    if neighbor not in neighborhoods:
        neighborhoods[neighbor] = []
    neighborhoods[neighbor].append(borough)

combined_areas = {}
for borough, neighbors in neighborhoods.items():
    combined_areas[borough] = [gas_data.loc[gas_data['borough'] == borough, 'Gas_value'].values[0]]
    for neighbor in neighbors:
        combined_areas[borough].append(gas_data.loc[gas_data['borough'] == neighbor, 'Gas_value'].values[0])
    combined_areas[borough] = np.mean(combined_areas[borough])

# Calculate the citywide average
citywide_average = np.mean(list(combined_areas.values()))

# Calculate the standard deviation
std_dev = np.std(list(combined_areas.values()))

# Calculate the z-score
z_scores = {}
for borough, value in combined_areas.items():
    z_scores[borough] = (value - citywide_average) / std_dev

# Identify hot and cold spots
hot_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96}
cold_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96 and borough not in hot_spots}

# Print results
data_points_used = len(gas_data)
results = []
for borough, z in hot_spots.items():
    results.append(f'{borough} (HOT, Gi*={z}, gi_value={z})')
for borough, z in cold_spots.items():
    results.append(f'{borough} (COLD, Gi*={z}, gi_value={z})')
if not results:
    results = ['none']
print(f'data_points_used = {data_points_used}')
print(f'FINAL ANSWER: {", ".join(results)}')
